(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[82],{2332:function(e,n,i){(window.__NEXT_P=window.__NEXT_P||[]).push(["/people/mohamed_ghanem",function(){return i(7091)}])},7091:function(e,n,i){"use strict";i.r(n),i.d(n,{useTOC:function(){return s}});var t=i(2676),r=i(2837),a=i(2339),o=i(146);function s(e){return[{value:"Research Interests:",id:"research-interests",depth:3}]}n.default=(0,r.c)(function(e){let{toc:n=s(e)}=e,i={h3:"h3",p:"p",...(0,o.a)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(i.p,{children:"Dr Mohamed Chahine Ghanem is an Associate Professor and Cyber Security Research Lead at Keele University (UK), and a Visiting Associate Professor in Cyber Security and AI within the Cybersecurity Institute at the University of Liverpool. He also holds a Senior Advisor position in Cyber Resilience within the banking sector. Before joining academia, Dr Ghanem built a strong industry foundation with over 15 years of practice in senior positions across law enforcement and corporations, including as Global Cyber Security Auditing Director for Kroll LLC and Nationwide Bank. He holds an Engineering Degree in Computer Systems from EMP (Algeria), an MSc in Digital Forensics & IT Security, and a PhD in Cyber Security Engineering from City, University of London. Dr Ghanem is a Senior Fellow of the Higher Education Academy (SFHEA), holds an MA in Academic Practice, and has earned numerous respected certifications including CISSP, CPCI, multiple GIAC credentials, and the Digital Forensics ACE & XRY qualifications. He currently leads a research programme in applied AI for cyber security and supervises research students working on digital forensics, IoT security, offensive cyber security, and applied AI, with a record of publications in Q1 journals. Dr Ghanem is also a regular keynote speaker at leading international cyber security conferences. He is Editor-in-Chief of the Journal of Cyber Security and Risk Auditing (Q1), an Editor with ACM Digital Threats: Research and Practice, and a Guest Editor and Reviewer for leading cybersecurity venues including JCP, IEEE Transactions on Information Forensics and Security (TIFS), and Elsevier Computers & Security."}),"\n",(0,t.jsx)(i.h3,{id:n[0].id,children:n[0].value}),"\n",(0,t.jsx)(i.p,{children:"Dr Ghanem’s research sits at the intersection of artificial intelligence, cyber security, and next-generation digital infrastructure including but not limited to:"}),"\n",(0,t.jsx)(i.p,{children:"Applied AI for Cyber Security \xb7 Intelligent & Intent-Aware Network Security \xb7 AI-Augmented Cyber Defence \xb7 Autonomous Cyber Operations \xb7 Offensive Security & Automated Testing \xb7 IoT & Edge–Cloud Security \xb7 Next-Generation Internet & Networking Protocols \xb7 Post-Quantum & Resilient Communications \xb7 Responsible & Governable AI"})]})},"/people/mohamed_ghanem",{filePath:"pages/people/mohamed_ghanem.mdx",pageMap:a.v,frontMatter:{title:"Mohamed Chahine Ghanem",image:"/people/m3.png",role:"Associate Professor\nKeele University",category:"C5_30",date:"2026/07/13",linkedin:"https://uk.linkedin.com/in/mohamed-chahine-ghanem-phd-cissp-sfhea-3665b010a",google_scholar:"https://scholar.google.co.uk/citations?user=gT0iu6IAAAAJ&hl=en",github:null},title:"Mohamed Chahine Ghanem"},"undefined"==typeof RemoteContent?s:RemoteContent.useTOC)}},function(e){e.O(0,[2837,2339,2888,9774,179],function(){return e(e.s=2332)}),_N_E=e.O()}]);